import json
import re
import sys


EXIT = {"decision": "exit"}


# Patterns that indicate the task wants a short, bare answer.  These are
# intentionally general and contain no task-specific answers.
_SHORT_ANSWER_PATTERNS = [
    re.compile(r"\bshort\s+answers?\b", re.IGNORECASE),
    re.compile(r"\bone[- ]word\b", re.IGNORECASE),
    re.compile(r"\bsingle\s+word\b", re.IGNORECASE),
    re.compile(r"\banswer\s+in\s+(?:a\s+few|one|two|three)\s+words?\b", re.IGNORECASE),
    re.compile(r"\banswer\s+with\s+only\b", re.IGNORECASE),
    re.compile(r"\breturn\s+only\b", re.IGNORECASE),
    re.compile(r"\bonly\s+the\s+(?:short\s+)?answer\b", re.IGNORECASE),
    re.compile(r"\bbare\s+answer\b", re.IGNORECASE),
    re.compile(r"\bno\s+explanation\b", re.IGNORECASE),
    re.compile(r"\bwithout\s+(?:any\s+)?explanation\b", re.IGNORECASE),
    re.compile(r"\bdo\s+not\s+explain\b", re.IGNORECASE),
    re.compile(r"\b(?:give|provide|return)\s+(?:only\s+)?the\s+(?:short\s+)?answer\b", re.IGNORECASE),
]

# Explanatory glue that should not appear in a bare short answer.
_EXPLANATION_PATTERNS = [
    re.compile(r"\balso known as\b", re.IGNORECASE),
    re.compile(r"\baka\b", re.IGNORECASE),
    re.compile(r"\ba\.k\.a\.?\b", re.IGNORECASE),
    re.compile(r"\bi\.e\.\b", re.IGNORECASE),
    re.compile(r"\be\.g\.\b", re.IGNORECASE),
    re.compile(r"\bfor example\b", re.IGNORECASE),
    re.compile(r"\bsuch as\b", re.IGNORECASE),
    re.compile(r"\bwhich is\b", re.IGNORECASE),
    re.compile(r"\bthat is\b", re.IGNORECASE),
    re.compile(r"\bmeaning\b", re.IGNORECASE),
    re.compile(r"\bbecause\b", re.IGNORECASE),
    re.compile(r"\brefers to\b", re.IGNORECASE),
    re.compile(r"\bfilm series\b", re.IGNORECASE),
]

# Trailing location/origin prepositions.  "of" is deliberately excluded because
# it is a normal part of many multi-word names (e.g. "President of the Senate").
# The object must look like a proper noun; phrases such as "in the Rye" are left
# alone so titles like "The Catcher in the Rye" are not flagged.
_TRAILING_PREPOSITION_RE = re.compile(
    r"\s+(?:in|on|at|near|from)\s+[A-Z][\w'.-]*(?:\s+[A-Z][\w'.-]*){0,3}$"
)

_LEADING_ARTICLES = {"a", "an", "the"}


def _message(obj):
    """Return a role/content message dict from any common transcript shape."""
    if not isinstance(obj, dict):
        return None
    if isinstance(obj.get("message"), dict):
        inner = obj["message"]
        if "role" in inner or "content" in inner:
            return inner
    if "role" in obj or "content" in obj:
        return obj
    if obj.get("type") in ("user", "assistant", "human", "ai"):
        return obj
    return None


def _role(msg):
    role = msg.get("role")
    if role:
        return str(role).lower()
    kind = msg.get("type")
    if kind in ("user", "human"):
        return "user"
    if kind in ("assistant", "ai"):
        return "assistant"
    return str(kind).lower() if kind else ""


def _text(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                text = item.get("text")
                if isinstance(text, str):
                    parts.append(text)
        return "\n".join(parts)
    return ""


def _read_transcript(path):
    """Read a Claude transcript (JSONL or JSON array) into message objects."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            raw = fh.read()
    except OSError:
        return []

    raw = raw.lstrip()
    if raw.startswith("["):
        try:
            decoded = json.loads(raw)
            if isinstance(decoded, list):
                return [_message(obj) for obj in decoded if _message(obj) is not None]
        except json.JSONDecodeError:
            pass

    messages = []
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(obj, list):
            messages.extend(_message(item) for item in obj if _message(item) is not None)
        else:
            msg = _message(obj)
            if msg is not None:
                messages.append(msg)
    return messages


def _fallback_messages(event):
    msg = _message(event)
    return [msg] if msg is not None else []


def _user_texts(messages):
    texts = []
    for msg in messages:
        if _role(msg) == "user":
            text = _text(msg.get("content"))
            if text.strip():
                texts.append(text)
    return texts


def _last_assistant_text(messages):
    for msg in reversed(messages):
        if _role(msg) == "assistant":
            text = _text(msg.get("content")).strip()
            if text:
                return text
    return None


def _wants_short_answer(messages):
    return any(
        pattern.search(text)
        for text in _user_texts(messages)
        for pattern in _SHORT_ANSWER_PATTERNS
    )


def _normalize_for_check(text):
    """Remove benign formatting that existing normalization already tolerates."""
    text = text.strip()
    # Markdown bold first, then any remaining asterisks.
    text = re.sub(r"\*\*([^*]+)\*\*", r"\1", text)
    text = text.replace("**", "").replace("*", "")
    # Inline code fences are also presentation, not answer content.
    text = text.replace("`", "")
    # Terminal punctuation is already normalized downstream; strip it before
    # checking for trailing prepositional phrases.
    text = re.sub(r"[.!?]+$", "", text).strip()
    text = text.strip("\"' ")
    return text


def _word_count(text):
    return len(text.split())


def _short_answer_violation(text):
    core = _normalize_for_check(text)
    if not core:
        return None

    # Parenthetical clauses and duplicate/alternate names in parentheses.
    if "(" in core or ")" in core:
        return "a parenthetical clause"

    # Em-dash / en-dash / double-hyphen justifications.
    if re.search(r"\s—\s|\s–\s|--", core):
        return "an em-dash justification"

    for pattern in _EXPLANATION_PATTERNS:
        if pattern.search(core):
            return "an explanatory aside"

    # A trailing locational/origin prepositional phrase attached to an already
    # multi-word answer, e.g. "Palazzo Pitti in Florence".
    match = _TRAILING_PREPOSITION_RE.search(core)
    if match:
        before = core[: match.start()].strip()
        first_word = before.split()[0].lower() if before.split() else ""
        if _word_count(before) >= 2 and first_word not in _LEADING_ARTICLES:
            return "a trailing prepositional phrase"

    # Slash-separated alternatives and explicit alternate-name markers.
    if re.search(r"\s/\s|\bor\s+the\s+|\balternatively\b", core, re.IGNORECASE):
        return "a repeated/alternate name"

    return None


def decide(event):
    if not isinstance(event, dict):
        return EXIT

    # The Stop hook must always permit exit when Claude is trying to stop after
    # a previous block; otherwise a single retry is enough.
    if event.get("stop_hook_active") is True:
        return EXIT

    transcript_path = event.get("transcript_path")
    messages = _read_transcript(transcript_path) if transcript_path else _fallback_messages(event)

    if not messages or not _wants_short_answer(messages):
        return EXIT

    answer = _last_assistant_text(messages)
    if answer is None:
        return EXIT

    violation = _short_answer_violation(answer)
    if violation is None:
        return EXIT

    return {
        "decision": "block",
        "reason": (
            "The task asks for a short answer, but the final response contains "
            + violation
            + ". Return only the bare short answer: no parentheticals, explanations, "
            "em-dash justifications, trailing prepositional phrases, or alternate names."
        ),
    }


if __name__ == "__main__":
    event = json.load(sys.stdin)
    print(json.dumps(decide(event)))

