import json
import re
import sys


# PreToolUse is the tool-interaction boundary. Only these read-only,
# supplied-context tools are allowed to run; anything else would let the model
# reach outside the supplied context (e.g. WebSearch or Bash).
_SAFE_PRE_TOOLS = frozenset({"Skill", "Read", "Glob", "Grep"})
_PRE_TOOL_DENIAL_REASON = (
    "Use only the supplied context; external tools are not allowed."
)

_BAD_ANSWER_FEEDBACK = (
    "Return only the requested short entity from the context; "
    "no yes/no, explanation, cast list, or title."
)

_BINARY_ANSWERS = {"yes", "no", "true", "false"}

_STRONG_SENTENCE_STARTERS = (
    "the answer is",
    "the correct answer is",
    "answer is",
    "the answer",
    "the correct answer",
    "the solution is",
    "the entity is",
    "it is",
    "this is",
    "that is",
    "there is",
    "there are",
    "here is",
    "he is",
    "she is",
    "it was",
    "he was",
    "she was",
    "they are",
    "they were",
    "the show is",
    "the show was",
    "the movie is",
    "the movie was",
    "the film is",
    "the film was",
    "the series is",
    "the series was",
    "the book is",
    "the book was",
    "the play is",
    "the play was",
    "the title is",
    "the cast is",
    "the character is",
    "the actor is",
    "the actress is",
    "i think",
    "i believe",
)

# Common single-word prepositions. A short prepositional phrase that is not
# title-case (for example ``By train``) is almost never the requested short
# entity, so it is not a recoverable answer.
_PREPOSITIONS = {
    "about", "above", "across", "after", "against", "along", "among",
    "around", "as", "at", "before", "behind", "below", "beneath",
    "beside", "between", "beyond", "by", "despite", "down", "during",
    "for", "from", "in", "inside", "into", "like", "near", "of", "off",
    "on", "onto", "out", "over", "past", "since", "through",
    "throughout", "till", "to", "toward", "towards", "under",
    "underneath", "until", "up", "upon", "with", "within", "without",
}


def _strip_outer_punctuation(text):
    """Remove balanced outer quotes/brackets, then leading/trailing punctuation."""
    cleaned = text.strip()
    pairs = [("(", ")"), ("[", "]"), ("{", "}"), ('"', '"'), ("'", "'")]
    changed = True
    while changed and len(cleaned) >= 2:
        changed = False
        for left, right in pairs:
            if cleaned.startswith(left) and cleaned.endswith(right):
                cleaned = cleaned[1:-1].strip()
                changed = True
                break

    # Strip loose sentence/quote punctuation from the ends only. Unpaired
    # closing brackets are left alone here so trailing parentheticals can be
    # handled separately.
    cleaned = cleaned.strip("\"'.,;:!?")
    return cleaned.strip()


def _strip_trailing_parentheticals(text):
    """Remove trailing parenthetical/bracketed qualifiers such as (born 1936)."""
    cleaned = text.strip()
    changed = True
    while changed:
        changed = False
        for pattern in (r"\s+\([^()]*\)\s*$", r"\s+\[[^\[\]]*\]\s*$", r"\s+\{[^{}]*\}\s*$"):
            new = re.sub(pattern, "", cleaned)
            if new != cleaned:
                cleaned = new.strip()
                changed = True
                break
    return cleaned.strip()


def _is_bad_candidate(cleaned):
    """Return True when the candidate is not a bare requested entity."""
    if not cleaned:
        return True
    lowered = cleaned.lower()
    if lowered in _BINARY_ANSWERS:
        return True
    if _is_full_sentence(cleaned):
        return True
    if _is_description_or_list(cleaned):
        return True
    if _is_bare_prepositional_phrase(cleaned):
        return True
    return False


def _is_bare_prepositional_phrase(text):
    """Reject short prepositional phrases that are not title-case entities.

    A phrase such as ``By train`` is sentence-case rather than a title, while a
    phrase with a later capitalized word such as ``On the Waterfront`` is kept.
    """
    words = text.split()
    if not words or len(words) < 2 or len(words) > 3:
        return False
    if words[0].lower() not in _PREPOSITIONS:
        return False
    for word in words[1:]:
        if word and word[0].isupper():
            return False
    return True


def _is_full_sentence(text):
    """Heuristic for full-sentence explanations instead of a bare entity."""
    cleaned = text.strip()
    words = cleaned.split()
    word_count = len(words)

    if word_count <= 2:
        return False

    # Internal sentence punctuation followed by a capital letter implies prose.
    if re.search(r"[.!?][\"')\]]?\s+[A-Z0-9]", cleaned):
        return True

    lowered = cleaned.lower()
    if lowered.startswith(_STRONG_SENTENCE_STARTERS):
        return True

    # Common copula/auxiliary verbs are a strong signal at this length.
    if re.search(r"\b(?:is|are|was|were|am)\b", lowered):
        return True
    if re.search(r"\b(?:has|have|had)\b", lowered):
        return True
    if re.search(r"\b(?:refers to|means|indicates|shows|denotes|represents)\b", lowered):
        return True
    if re.search(r"\b(?:includes|include|consists of|contains|contain)\b", lowered):
        return True
    if re.search(
        r"\b(?:played|plays|portrayed|portrays|starred|stars|features|featured|"
        r"directed|directs|wrote|writes|created|creates|served as|became|become|"
        r"scores?)\b",
        lowered,
    ):
        return True

    return False


def _is_description_or_list(text):
    """Heuristic for titles/cast lists/descriptions instead of a short entity."""
    cleaned = text.strip()
    lowered = cleaned.lower()
    word_count = len(cleaned.split())

    if not cleaned:
        return True

    # Lists and multi-line prose are not short entities.
    if "\n" in cleaned or "\t" in cleaned:
        return True
    if re.search(r"^\s*(?:[-*+]\s+|\d+[.)]\s+)", cleaned):
        return True
    if cleaned.count(",") >= 2 and word_count >= 4:
        return True
    if word_count > 10:
        return True

    # Em/en dashes and semicolons join explanatory clauses, not a short entity.
    if any(ch in cleaned for ch in ("—", "–", ";")):
        return True

    # A colon plus trailing explanation is prose, not a short answer.
    if ":" in cleaned and word_count >= 5:
        return True

    # Explicit cast/character/description vocabulary is a different answer mode.
    if word_count >= 4 and re.search(
        r"\b(?:cast|character|characters|actor|actors|actress|actresses|"
        r"director|directed by|played by|starring|role of|episode|plot|premise)\b",
        lowered,
    ):
        return True

    return False


def _strip_trailing_explanatory_clauses(text):
    """Remove trailing explanatory clauses from a candidate.

    Parentheticals, semicolon clauses, and spaced dash clauses are removed when
    the remaining prefix is a valid short entity. A trailing comma clause is
    removed only when it is substantial enough to be explanatory (three or more
    words) or when it is a bare year/date qualifier, so short comma-separated
    names such as ``Washington, D.C.`` are preserved.
    """
    cleaned = text.strip()
    changed = True
    while changed:
        changed = False

        before = cleaned
        cleaned = _strip_trailing_parentheticals(cleaned)
        if cleaned != before:
            changed = True
            continue

        # Semicolons and spaced em/en dashes are always clause separators here.
        # Match the whole trailing clause so en dashes or other punctuation
        # inside the clause do not prevent stripping.
        for pattern in (r"\s*;\s*(.*)$", r"\s+[—–-]\s+(.*)$"):
            new = re.sub(pattern, "", cleaned, flags=re.DOTALL).strip()
            if new != cleaned and new and not _is_bad_candidate(new):
                cleaned = new
                changed = True
                break
        if changed:
            continue

        # Comma clauses are only stripped when the trailing clause is long
        # enough to be an explanation rather than a short name component, or
        # when it is a bare year/date qualifier (``M*A*S*H, 1970``).
        match = re.search(r"\s*,\s*([^,]+)$", cleaned)
        if match:
            suffix = match.group(1).strip()
            explanatory_comma_clause = len(suffix.split()) >= 3 or re.match(
                r"^(?:1[0-9]{3}|20[0-9]{2})(?:s)?$", suffix
            )
            if explanatory_comma_clause:
                new = cleaned[: match.start()].strip()
                if new and not _is_bad_candidate(new):
                    cleaned = new
                    changed = True

    return cleaned.strip()


def _strip_trailing_qualifiers_and_punctuation(text):
    """Remove trailing qualifiers and punctuation from a final candidate.

    This is intentionally narrow: it strips trailing parenthetical/bracketed
    qualifiers, explanatory clauses, and outer/trailing punctuation only. It
    leaves Markdown emphasis, capitalization, and leading articles intact so
    short entities that already have the right surface form are not disturbed.
    """
    cleaned = text.strip()
    changed = True
    while changed:
        changed = False
        before = cleaned
        # Strip balanced quote/bracket wrappers and trailing sentence
        # punctuation first, so a trailing qualifier such as
        # ``(the Great Highland bagpipe).`` can be recognized and removed.
        cleaned = _strip_outer_punctuation(cleaned)
        cleaned = _strip_trailing_explanatory_clauses(cleaned)
        if cleaned != before:
            changed = True
    return cleaned.strip()


def before_final(candidate):
    """Stop-hook decision for the final answer candidate.

    Cleanup is conservative and conditional. If the candidate is already a
    short entity, it is returned unchanged, preserving Markdown emphasis,
    capitalization, and leading articles. Trailing qualifiers and punctuation
    are removed only when present. Candidates that use a non-entity answer mode
    (yes/no/true/false, an explanation, a cast list, or a title) are rejected
    so the model can return the requested short entity.
    """
    if not isinstance(candidate, str):
        return {"action": "continue", "feedback": _BAD_ANSWER_FEEDBACK}

    raw = candidate.strip()
    if not raw:
        return {"action": "continue", "feedback": _BAD_ANSWER_FEEDBACK}

    cleaned = _strip_trailing_qualifiers_and_punctuation(raw)

    if cleaned != raw:
        if _is_bad_candidate(cleaned):
            return {"action": "continue", "feedback": _BAD_ANSWER_FEEDBACK}
        return {"action": "replace", "answer": cleaned}

    if _is_bad_candidate(raw):
        return {"action": "continue", "feedback": _BAD_ANSWER_FEEDBACK}

    return {"action": "replace", "answer": raw}


def _extract_candidate(event):
    """Find a final-answer candidate string in a Stop-hook event payload."""
    if not isinstance(event, dict):
        return None

    candidate_keys = (
        "answer",
        "candidate",
        "final_answer",
        "final_response",
        "response",
        "output",
        "text",
        "content",
        "message",
        "value",
    )
    for key in candidate_keys:
        value = event.get(key)
        if isinstance(value, str) and value.strip():
            return value
        if isinstance(value, dict):
            found = _extract_candidate(value)
            if found is not None:
                return found
        if isinstance(value, list):
            for item in value:
                if isinstance(item, str) and item.strip():
                    return item
                if isinstance(item, dict):
                    found = _extract_candidate(item)
                    if found is not None:
                        return found

    stop = event.get("stop")
    if isinstance(stop, dict):
        found = _extract_candidate(stop)
        if found is not None:
            return found

    return None


def decide(event):
    """Handle PreToolUse/PostToolUse/Stop hook events.

    PreToolUse denies every tool outside the fixed read-only, supplied-context
    set. PostToolUse remains permissive so it never grants new permissions.
    Stop applies conservative final-answer boundary cleanup.
    """
    if not isinstance(event, dict):
        return {}

    hook_event_name = event.get("hook_event_name")

    if hook_event_name == "PreToolUse":
        tool_name = event.get("tool_name")
        if tool_name not in _SAFE_PRE_TOOLS:
            return {
                "hookSpecificOutput": {
                    "hookEventName": "PreToolUse",
                    "permissionDecision": "deny",
                    "permissionDecisionReason": _PRE_TOOL_DENIAL_REASON,
                }
            }
        return {}

    if hook_event_name == "Stop" and event.get("stop_hook_active") is True:
        candidate = _extract_candidate(event)
        if candidate is None:
            # A Stop hook must allow Claude to exit when no candidate is
            # available; continue is the permissive Stop-hook action.
            return {"action": "continue"}
        return before_final(candidate)

    return {}


if __name__ == "__main__":
    event = json.load(sys.stdin)
    print(json.dumps(decide(event)))

